rep1("  if(D.lamps)buildLamps(D.lamps);\n  /* 출발선","  if(D.lamps)buildLamps(D.lamps);\n  }\n  /* 출발선")
rep1("mbg.closePath()};","if(!OPENP)mbg.closePath()};")
rep1("path();mbg.strokeStyle='#3a3f52';mbg.lineWidth=3.6*mdpr;mbg.stroke();","path();mbg.strokeStyle='#3a3f52';mbg.lineWidth=3.6*mdpr;mbg.stroke();\n  if(JMP){const a=TP[JMP.iLip],b=TP[JMP.iLand];mbg.strokeStyle='#2f7fe0';mbg.lineWidth=7*mdpr;mbg.beginPath();mbg.moveTo(a[0]*msc+mox,a[1]*msc+moz);mbg.lineTo(b[0]*msc+mox,b[1]*msc+moz);mbg.stroke()}")
